<?php
ini_set('display_errors', 0); error_reporting(E_ALL);
define('BASE_PATH', dirname(__DIR__)); define('CONFIG_DIR', BASE_PATH . '/config'); define('SQL_DIR', BASE_PATH . '/sql');
$installLockFile = CONFIG_DIR . '/install.lock';
if (file_exists($installLockFile)) { die('<h1 style="text-align:center;padding:50px;font-family:tahoma;">✅ نصب تکمیل شده است</h1>'); }
$dbConfigFile = CONFIG_DIR . '/database.php'; $schemaFile = SQL_DIR . '/install_schema.sql';
$step = isset($_GET['step']) ? (int)$_GET['step'] : 1; $errors = []; $success = false; $adminCredentials = null;
if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_POST['step'])) {
    $step = (int)$_POST['step'];
    if ($step === 1) {
        $host = trim($_POST['db_host'] ?? ''); $port = trim($_POST['db_port'] ?? '3306'); $database = trim($_POST['db_name'] ?? ''); $username = trim($_POST['db_user'] ?? ''); $password = $_POST['db_pass'] ?? '';
        if (empty($host) || empty($database) || empty($username)) { $errors[] = 'تمامی فیلدها الزامی هستند.'; }
        else {
            try {
                $dsn = "mysql:host={$host};port={$port};charset=utf8mb4";
                $pdo = new PDO($dsn, $username, $password, [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC]);
                $pdo->exec("CREATE DATABASE IF NOT EXISTS `{$database}` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci"); $pdo->exec("USE `{$database}`");
                $dbConfigContent = "<?php\nreturn ['host' => '".addslashes($host)."', 'port' => '".addslashes($port)."', 'database' => '".addslashes($database)."', 'username' => '".addslashes($username)."', 'password' => '".addslashes($password)."', 'charset' => 'utf8mb4', 'options' => [PDO::ATTR_ERRMODE => PDO::ATTR_ERRMODE_EXCEPTION, PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC, PDO::ATTR_EMULATE_PREPARES => false]];\n";
                if (file_put_contents($dbConfigFile, $dbConfigContent) !== false) { $success = true; $step = 2; } else { $errors[] = 'خطا در ایجاد فایل تنظیمات.'; }
            } catch (PDOException $e) { $errors[] = 'خطا در اتصال به دیتابیس: ' . $e->getMessage(); }
        }
    } elseif ($step === 2) {
        try {
            if (!file_exists($dbConfigFile)) { throw new Exception('فایل تنظیمات یافت نشد.'); }
            $dbConfig = require $dbConfigFile;
            $dsn = "mysql:host={$dbConfig['host']};port={$dbConfig['port']};dbname={$dbConfig['database']};charset=utf8mb4";
            $pdo = new PDO($dsn, $dbConfig['username'], $dbConfig['password'], $dbConfig['options']);
            if (!file_exists($schemaFile)) { throw new Exception('فایل اسکیمای دیتابیس یافت نشد.'); }
            $sql = file_get_contents($schemaFile); $statements = array_filter(array_map('trim', explode(';', $sql)));
            foreach ($statements as $statement) { if (!empty($statement) && !preg_match('/^--/', $statement)) { $pdo->exec($statement); } }
            $adminUsername = trim($_POST['admin_username'] ?? 'admin'); $adminPassword = password_hash($_POST['admin_password'] ?? 'admin123', PASSWORD_DEFAULT); $adminEmail = trim($_POST['admin_email'] ?? 'admin@example.com');
            $stmt = $pdo->prepare("INSERT INTO users (username, email, password, role, created_at) VALUES (?, ?, ?, 'admin', NOW())"); $stmt->execute([$adminUsername, $adminEmail, $adminPassword]);
            $adminCredentials = ['username' => $adminUsername, 'password' => $_POST['admin_password'] ?? 'admin123'];
            if (file_put_contents($installLockFile, date('Y-m-d H:i:s')) !== false) { $success = true; $step = 3; } else { $errors[] = 'خطا در ایجاد فایل قفل.'; }
        } catch (Exception $e) { $errors[] = 'خطا در نصب: ' . $e->getMessage(); }
    }
}
?>
<!DOCTYPE html><html lang="fa" dir="rtl"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>نصب DomainHub</title>
<style>*{margin:0;padding:0;box-sizing:border-box}body{font-family:'Segoe UI',Tahoma,Geneva,Verdana,sans-serif;background:linear-gradient(135deg,#667eea 0%,#764ba2 100%);min-height:100vh;display:flex;align-items:center;justify-content:center;padding:20px}.installer-container{background:white;border-radius:20px;box-shadow:0 20px 60px rgba(0,0,0,0.3);max-width:650px;width:100%;overflow:hidden;animation:slideIn 0.5s ease-out}@keyframes slideIn{from{opacity:0;transform:translateY(30px)}to{opacity:1;transform:translateY(0)}}.header{background:linear-gradient(135deg,#667eea 0%,#764ba2 100%);color:white;padding:40px 30px;text-align:center}.header h1{font-size:2em;margin-bottom:10px;font-weight:700}.header p{opacity:0.9;font-size:0.95em}.progress-bar{display:flex;justify-content:space-between;padding:30px 40px;background:#f8f9fa;border-bottom:1px solid #e9ecef}.progress-step{display:flex;flex-direction:column;align-items:center;position:relative;flex:1}.progress-step:not(:last-child)::after{content:'';position:absolute;top:15px;left:60%;width:80%;height:2px;background:#e9ecef}.progress-step.active:not(:last-child)::after{background:#667eea}.step-number{width:30px;height:30px;border-radius:50%;background:#e9ecef;color:#6c757d;display:flex;align-items:center;justify-content:center;font-weight:bold;font-size:0.9em;margin-bottom:8px;transition:all 0.3s ease;z-index:1}.progress-step.active .step-number{background:#667eea;color:white}.progress-step.completed .step-number{background:#28a745;color:white}.step-label{font-size:0.85em;color:#6c757d;font-weight:500}.progress-step.active .step-label{color:#667eea;font-weight:600}.content{padding:40px 30px}.form-group{margin-bottom:25px}.form-group label{display:block;margin-bottom:8px;color:#495057;font-weight:600;font-size:0.95em}.form-group input{width:100%;padding:12px 15px;border:2px solid #e9ecef;border-radius:10px;font-size:1em;transition:all 0.3s ease;font-family:inherit}.form-group input:focus{outline:none;border-color:#667eea;box-shadow:0 0 0 3px rgba(102,126,234,0.1)}.form-group small{display:block;margin-top:5px;color:#6c757d;font-size:0.85em}.alert{padding:15px 20px;border-radius:10px;margin-bottom:25px;font-size:0.95em}.alert-error{background:#f8d7da;color:#721c24;border:1px solid #f5c6cb}.alert-success{background:#d4edda;color:#155724;border:1px solid #c3e6cb}.alert-info{background:#d1ecf1;color:#0c5460;border:1px solid #bee5eb}.btn{padding:14px 30px;border:none;border-radius:10px;font-size:1em;font-weight:600;cursor:pointer;transition:all 0.3s ease;font-family:inherit}.btn-primary{background:linear-gradient(135deg,#667eea 0%,#764ba2 100%);color:white;width:100%}.btn-primary:hover{transform:translateY(-2px);box-shadow:0 5px 20px rgba(102,126,234,0.4)}.btn-primary:disabled{opacity:0.6;cursor:not-allowed;transform:none}.success-message{text-align:center;padding:30px 20px}.success-icon{width:80px;height:80px;background:linear-gradient(135deg,#28a745 0%,#20c997 100%);border-radius:50%;display:flex;align-items:center;justify-content:center;margin:0 auto 25px;animation:scaleIn 0.5s ease-out}@keyframes scaleIn{from{transform:scale(0)}to{transform:scale(1)}}.success-icon svg{width:40px;height:40px;fill:white}.success-message h2{color:#28a745;margin-bottom:15px;font-size:1.8em}.success-message p{color:#6c757d;margin-bottom:25px;line-height:1.6}.credentials-box{background:#fff3cd;border:2px solid #ffc107;border-radius:10px;padding:20px;margin:25px 0;text-align:center}.credentials-box h3{color:#856404;margin-bottom:15px}.credential-item{background:white;padding:10px 15px;border-radius:8px;margin:10px 0;display:flex;justify-content:space-between;align-items:center}.credential-label{font-weight:600;color:#495057}.credential-value{font-family:monospace;background:#f8f9fa;padding:5px 10px;border-radius:5px;color:#667eea}.next-steps{background:#f8f9fa;padding:20px;border-radius:10px;margin-top:25px}.next-steps h3{color:#495057;margin-bottom:15px;font-size:1.1em}.next-steps ul{list-style:none;padding:0}.next-steps li{padding:8px 0;color:#6c757d;position:relative;padding-right:25px}.next-steps li::before{content:'✓';position:absolute;right:0;color:#28a745;font-weight:bold}.warning-box{background:#fff3cd;border:1px solid #ffc107;border-radius:10px;padding:15px;margin-top:20px;color:#856404;font-size:0.9em}.api-info{background:#e7f3ff;border:1px solid #b3d9ff;border-radius:10px;padding:15px;margin-top:15px;color:#004085;font-size:0.9em}</style></head>
<body><div class="installer-container"><div class="header"><h1>🚀 نصب DomainHub</h1><p>سیستم حرفه‌ای جستجو و ثبت دامنه‌های اینترنتی</p></div>
<div class="progress-bar"><div class="progress-step <?php echo $step>=1?'active':'';?> <?php echo $step>1?'completed':'';?>"><div class="step-number"><?php echo $step>1?'✓':'1';?></div><div class="step-label">تنظیمات دیتابیس</div></div><div class="progress-step <?php echo $step>=2?'active':'';?> <?php echo $step>2?'completed':'';?>"><div class="step-number"><?php echo $step>2?'✓':'2';?></div><div class="step-label">ایجاد جداول</div></div><div class="progress-step <?php echo $step>=3?'active':'';?>"><div class="step-number"><?php echo $step>=3?'✓':'3';?></div><div class="step-label">پایان نصب</div></div></div>
<div class="content"><?php if(!empty($errors)):?><div class="alert alert-error"><strong>⚠️ خطا:</strong><ul style="margin:10px 0 0 20px;"><?php foreach($errors as $error):?><li><?php echo htmlspecialchars($error);?></li><?php endforeach;?></ul></div><?php endif;?>
<?php if($step===1):?><div class="alert alert-info"><strong>📋 اطلاعات مورد نیاز:</strong><br>برای ادامه نصب، به اطلاعات دیتابیس MySQL خود نیاز دارید.</div><form method="POST"><input type="hidden" name="step" value="1"><div class="form-group"><label for="db_host">آدرس سرور دیتابیس (Host)</label><input type="text" id="db_host" name="db_host" value="<?php echo htmlspecialchars($_POST['db_host']??'localhost');?>" required><small>معمولاً localhost است</small></div><div class="form-group"><label for="db_port">پورت دیتابیس</label><input type="number" id="db_port" name="db_port" value="<?php echo htmlspecialchars($_POST['db_port']??'3306');?>" required><small>پورت پیش‌فرض MySQL: 3306</small></div><div class="form-group"><label for="db_name">نام دیتابیس</label><input type="text" id="db_name" name="db_name" value="<?php echo htmlspecialchars($_POST['db_name']??'');?>" required><small>در صورت عدم وجود، ساخته خواهد شد</small></div><div class="form-group"><label for="db_user">نام کاربری دیتابیس</label><input type="text" id="db_user" name="db_user" value="<?php echo htmlspecialchars($_POST['db_user']??'');?>" required><small>نام کاربری MySQL با دسترسی کامل</small></div><div class="form-group"><label for="db_pass">رمز عبور دیتابیس</label><input type="password" id="db_pass" name="db_pass" value="<?php echo htmlspecialchars($_POST['db_pass']??'');?>"><small>در صورت عدم نیاز خالی بگذارید</small></div><button type="submit" class="btn btn-primary">🔗 بررسی اتصال و ادامه</button></form>
<?php elseif($step===2):?><div class="alert alert-success">✅ اتصال به دیتابیس با موفقیت برقرار شد.<br>حالا باید اطلاعات مدیر کل سیستم را وارد کنید.</div><form method="POST"><input type="hidden" name="step" value="2"><div class="api-info"><strong>🔧 نکته مهم:</strong><br>پس از نصب، می‌توانید تنظیمات پیشرفته مانند API Key Namecheap را از پنل مدیریت تغییر دهید.</div><div class="form-group"><label for="admin_username">نام کاربری مدیر کل</label><input type="text" id="admin_username" name="admin_username" value="<?php echo htmlspecialchars($_POST['admin_username']??'admin');?>" required><small>برای ورود به پنل مدیریت</small></div><div class="form-group"><label for="admin_password">رمز عبور مدیر کل</label><input type="password" id="admin_password" name="admin_password" value="<?php echo htmlspecialchars($_POST['admin_password']??'admin123');?>" required><small>حداقل ۸ کاراکتر توصیه می‌شود</small></div><div class="form-group"><label for="admin_email">ایمیل مدیر</label><input type="email" id="admin_email" name="admin_email" value="<?php echo htmlspecialchars($_POST['admin_email']??'admin@example.com');?>" required><small>برای اطلاع‌رسانی‌های سیستم</small></div><button type="submit" class="btn btn-primary">📦 ایجاد جداول و تکمیل نصب</button></form>
<?php elseif($step===3&&$success):?><div class="success-message"><div class="success-icon"><svg viewBox="0 0 24 24"><path d="M9 16.17L4.83 12l-1.42 1.41L9 19 21 7l-1.41-1.41z"/></svg></div><h2>✅ نصب با موفقیت تکمیل شد!</h2><p>سیستم DomainHub آماده استفاده است.</p><?php if($adminCredentials):?><div class="credentials-box"><h3>🔐 اطلاعات ورود به پنل مدیریت</h3><div class="credential-item"><span class="credential-label">نام کاربری:</span><span class="credential-value"><?php echo htmlspecialchars($adminCredentials['username']);?></span></div><div class="credential-item"><span class="credential-label">رمز عبور:</span><span class="credential-value"><?php echo htmlspecialchars($adminCredentials['password']);?></span></div><p style="color:#856404;font-size:0.85em;margin-top:15px;">⚠️ این اطلاعات را در جای امنی ذخیره کنید و پس از اولین ورود رمز عبور را تغییر دهید.</p></div><?php endif;?>
<div class="next-steps"><h3>📌 مراحل بعدی:</h3><ul><li>حذف فایل install.php به دلایل امنیتی</li><li>ورود به پنل مدیریت با اطلاعات بالا</li><li>تنظیم API Key Namecheap برای جستجوی دامنه</li><li>تعریف کارت‌های بانکی برای پرداخت دستی</li><li>تنظیم منابع نرخ ارز (اختیاری)</li><li>شروع به کار سیستم!</li></ul></div><div class="warning-box"><strong>⚠️ هشدار امنیتی:</strong><br>لطفاً فایل <code>public/install.php</code> را پس از اطمینان از نصب صحیح حذف کنید.</div><div style="margin-top:30px;"><a href="../" class="btn btn-primary" style="display:inline-block;text-decoration:none;width:auto;">🏠 مشاهده سایت</a><a href="../admin" class="btn btn-primary" style="display:inline-block;text-decoration:none;width:auto;background:linear-gradient(135deg,#28a745 0%,#20c997 100%);margin-right:10px;">🔐 ورود به پنل مدیریت</a></div></div><?php endif;?></div></div></body></html>
